const { exec } = require('child_process');
const fs = require('fs');
const players = $input.all().map(item => item.json);
fs.writeFileSync('/tmp/players.json', JSON.stringify(players));

const stdout = await new Promise((resolve, reject) => {
  exec('node /opt/n8n-custom/fotmob-scraper.js /tmp/players.json', {
    timeout: 600000,
    maxBuffer: 50 * 1024 * 1024
  }, (error, stdout, stderr) => {
    if (error) reject(new Error(stderr || error.message));
    else resolve(stdout);
  });
});

const results = JSON.parse(stdout);
return results.map(r => ({ json: r }));

// Google Sheets는 flat structure만 지원하므로 변환 필요
const items = $input.all().map(item => item.json);

const flattenedData = items.map(data => {
  return {
    // 메타
    collection_date: data.collection_date,
    week: data.week,

    // 기본 정보
    player_id: data.id,
    player_name: data.name,
    player_name_kr: data.name_kr,
    team: data.team,
    league: data.league,
    position: data.position,

    // 주간 통계 (flatten)
    weekly_matches: data.weekly_stats?.matches || 0,
    weekly_minutes: data.weekly_stats?.minutes || 0,
    weekly_goals: data.weekly_stats?.goals || 0,
    weekly_assists: data.weekly_stats?.assists || 0,
    weekly_avg_rating: data.weekly_stats?.avg_rating || 0,
    weekly_mvp_score: data.weekly_stats?.mvp_score || 0,

