// ============================================
// n8n Node: Player Profile Data Processing
// FotMob API → Player Profile Stats (player_profile_stats.csv용)
// ============================================

// ========== Helper Functions ==========

function safeGet(obj, ...keys) {
  return keys.reduce((acc, key) => (acc && acc[key] !== undefined ? acc[key] : null), obj);
}

function parseFloat2(value) {
  if (value == null || value === '') return 0;
  const parsed = parseFloat(value);
  return isNaN(parsed) ? 0 : Math.round(parsed * 100) / 100;
}

function parseInt2(value) {
  if (value == null || value === '') return 0;
  const parsed = parseInt(value);
  return isNaN(parsed) ? 0 : parsed;
}

function parsePercent(value) {
  if (value == null || value === '') return 0;
  const strVal = String(value).replace('%', '');
  return parseFloat2(strVal);
}

function calculateAge(birthDateStr) {
  if (!birthDateStr) return null;
  const birth = new Date(birthDateStr);
  const today = new Date();
  let age = today.getFullYear() - birth.getFullYear();
  const monthDiff = today.getMonth() - birth.getMonth();
  if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
    age--;
  }
  return age;
}

function getPlayerInfoValue(playerInfo, key) {
  if (!Array.isArray(playerInfo)) return '';
  const item = playerInfo.find(info => info.title === key);
  return item?.value?.fallback || '';
}

function getStatValue(statsSection, category, statKey) {
  if (!statsSection || !statsSection.items || !Array.isArray(statsSection.items)) return null;

  const categoryData = statsSection.items.find(item => item.localizedTitleId === category);
  if (!categoryData || !categoryData.items || !Array.isArray(categoryData.items)) return null;

  const stat = categoryData.items.find(s => s.localizedTitleId === statKey);
  if (!stat) return null;

  // statValue가 문자열인 경우 파싱
  if (stat.statValue != null) {
    const strVal = String(stat.statValue);
    if (strVal.includes('%')) return parsePercent(strVal);
    if (strVal.includes('.')) return parseFloat2(strVal);
    return parseInt2(strVal);
  }

  return null;
}

// ========== Section Extractors ==========

// Section 1: Profile Header (18개 필드 - birth_date, nationality 제거)
function extractProfileHeader(api) {
  const playerInfo = api.playerInformation || [];
  const birthDate = safeGet(api, 'birthDate', 'utcTime');

  return {
    player_id: api.id || null,
    player_name: api.name || '',
    player_name_kr: '', // 별도 매핑 필요
    age: calculateAge(birthDate),
    height: getPlayerInfoValue(playerInfo, 'Height'),
    preferred_foot: getPlayerInfoValue(playerInfo, 'Preferred foot'),
    shirt_number: getPlayerInfoValue(playerInfo, 'Shirt number'),
    position: safeGet(api, 'positionDescription', 'primaryPosition', 'label') || '',
    team: safeGet(api, 'primaryTeam', 'teamName') || '',
    team_id: safeGet(api, 'primaryTeam', 'teamId') || null,
    league: safeGet(api, 'mainLeague', 'leagueName') || '',
    league_id: safeGet(api, 'mainLeague', 'leagueId') || null,
    season: safeGet(api, 'mainLeague', 'season') || '',
    market_value: getPlayerInfoValue(playerInfo, 'Market value'),
    contract_end: safeGet(api, 'contractEnd', 'utcTime') || null,
    is_injured: !!api.injuryInformation,
    injury_status: safeGet(api, 'injuryInformation', 'name') || null,
    fotmob_url: api.id ? `https://www.fotmob.com/players/${api.id}` : ''
  };
}

// Section 2: Key Stats Cards (6개 필드 - per90/percentile 제거)
function extractKeyStats(firstSeasonStats) {
  const topStatCard = firstSeasonStats?.topStatCard?.items || [];
  const result = {};

  const statKeys = ['goals', 'assists', 'rating', 'matches_uppercase', 'player_started_matches', 'minutes_played'];
  const statMapping = {
    'matches_uppercase': 'matches',
    'player_started_matches': 'started'
  };

  statKeys.forEach(key => {
    const statData = topStatCard.find(s => s.localizedTitleId === key);
    const outputKey = statMapping[key] || key;

    result[outputKey] = statData?.statValue != null ? parseFloat2(statData.statValue) : 0;
  });

  return result;
}

// Section 3: Attack (7개 필드 - xg_difference, shots, shots_on_target, shooting_accuracy, big_chances_missed 제거)
function extractAttackStats(firstSeasonStats) {
  const statsSection = firstSeasonStats?.statsSection;

  const goals = getStatValue(statsSection, 'shooting', 'goals') || 0;
  const shots = getStatValue(statsSection, 'shooting', 'shots') || 0;

  return {
    attack_goals: goals,
    attack_expected_goals: getStatValue(statsSection, 'shooting', 'expected_goals') || 0,
    attack_non_penalty_xg: getStatValue(statsSection, 'shooting', 'non_penalty_xg') || 0,
    attack_conversion_rate: shots > 0 ? Math.round((goals / shots) * 10000) / 100 : 0,
    attack_dribbles_succeeded: getStatValue(statsSection, 'possession', 'dribbles_succeeded') || 0,
    attack_dribble_success_rate: parsePercent(getStatValue(statsSection, 'possession', 'won_contest_subtitle')),
    attack_touches_in_box: getStatValue(statsSection, 'possession', 'touches_opp_box') || 0
  };
}

// Section 4: Passing (9개 필드 - xa_difference, key_passes 제거)
function extractPassingStats(firstSeasonStats) {
  const statsSection = firstSeasonStats?.statsSection;

  return {
    passing_assists: getStatValue(statsSection, 'passing', 'assists') || 0,
    passing_expected_assists: getStatValue(statsSection, 'passing', 'expected_assists') || 0,
    passing_chances_created: getStatValue(statsSection, 'passing', 'chances_created') || 0,
    passing_successful_passes: getStatValue(statsSection, 'passing', 'successful_passes') || 0,
    passing_pass_accuracy: getStatValue(statsSection, 'passing', 'successful_passes_accuracy') || 0,
    passing_long_balls_accurate: getStatValue(statsSection, 'passing', 'long_balls_accurate') || 0,
    passing_long_ball_accuracy: getStatValue(statsSection, 'passing', 'long_ball_succeeeded_accuracy') || 0,
    passing_crosses_accurate: getStatValue(statsSection, 'passing', 'crosses_succeeeded') || 0,
    passing_cross_accuracy: getStatValue(statsSection, 'passing', 'crosses_succeeeded_accuracy') || 0
  };
}

// Section 5: Possession (2개 필드 - touches, touches_in_box, fouls_won 제거)
function extractPossessionStats(firstSeasonStats) {
  const statsSection = firstSeasonStats?.statsSection;

  return {
    possession_dispossessed: getStatValue(statsSection, 'possession', 'dispossessed') || 0,
    possession_penalty_won: parseInt2(getStatValue(statsSection, 'possession', 'penalty_won_title'))
  };
}

// Section 6: Defense (9개 필드 - tackles_successful, tackle_success_rate, clearances, ground_duels_won, ground_duel_success_rate, fouls_committed 제거)
function extractDefenseStats(firstSeasonStats) {
  const statsSection = firstSeasonStats?.statsSection;

  return {
    defense_tackles: getStatValue(statsSection, 'defending', 'matchstats.headers.tackles') || 0,
    defense_interceptions: getStatValue(statsSection, 'defending', 'interceptions') || 0,
    defense_blocked_shots: getStatValue(statsSection, 'defending', 'blocked_shots') || 0,
    defense_duels_won: getStatValue(statsSection, 'defending', 'duel_won') || 0,
    defense_duel_success_rate: getStatValue(statsSection, 'defending', 'duel_won_percent') || 0,
    defense_aerials_won: getStatValue(statsSection, 'defending', 'aerials_won') || 0,
    defense_aerial_success_rate: getStatValue(statsSection, 'defending', 'aerials_won_percent') || 0,
    defense_recoveries: getStatValue(statsSection, 'defending', 'recoveries') || 0,
    defense_dribbled_past: getStatValue(statsSection, 'defending', 'dribbled_past') || 0
  };
}

// Section 7: Discipline (4개 필드)
function extractDisciplineStats(firstSeasonStats) {
  const statsSection = firstSeasonStats?.statsSection;

  return {
    discipline_yellow_cards: getStatValue(statsSection, 'discipline', 'yellow_cards') || 0,
    discipline_red_cards: getStatValue(statsSection, 'discipline', 'red_cards') || 0,
    discipline_fouls_committed: getStatValue(statsSection, 'defending', 'fouls') || 0,
    discipline_fouls_won: getStatValue(statsSection, 'possession', 'fouls_won') || 0
  };
}

// Section 8: Shot Analysis (9개 필드 - goals, blocked, off_target, total_xg, quality 제거)
function extractShotAnalysis(firstSeasonStats) {
  const statsSection = firstSeasonStats?.statsSection;
  const shotmap = firstSeasonStats?.shotmap || [];

  // statsSection에서 정확한 총 슈팅과 유효 슈팅 가져오기
  const totalShots = getStatValue(statsSection, 'shooting', 'shots') || 0;
  const onTargetFromStats = getStatValue(statsSection, 'shooting', 'ShotsOnTarget') || 0;

  // shotmap에서 상세 분석 데이터 계산
  const leftFoot = shotmap.filter(s => s.situation === 'RegularPlay' && s.shotType?.includes('LeftFoot')).length;
  const rightFoot = shotmap.filter(s => s.situation === 'RegularPlay' && s.shotType?.includes('RightFoot')).length;
  const headed = shotmap.filter(s => s.shotType?.includes('Header')).length;

  const openPlay = shotmap.filter(s => s.situation === 'RegularPlay').length;
  const freeKick = shotmap.filter(s => s.situation === 'FreeKick').length;
  const penalty = shotmap.filter(s => s.situation === 'Penalty').length;

  // shotmap 데이터가 있을 때만 비율 계산, 없으면 0
  const shotmapLength = shotmap.length;
  const preferredFootShots = Math.max(leftFoot, rightFoot);
  const preferredFootRatio = shotmapLength > 0 ? Math.round((preferredFootShots / shotmapLength) * 10000) / 100 : 0;

  return {
    shot_total_shots: totalShots,
    shot_on_target: onTargetFromStats,
    shot_left_foot: leftFoot,
    shot_right_foot: rightFoot,
    shot_headed: headed,
    shot_open_play: openPlay,
    shot_free_kick: freeKick,
    shot_penalty: penalty,
    shot_preferred_foot_ratio: preferredFootRatio
  };
}

// ========== Main Processing ==========

const allData = $input.all().map(item => item.json);
const successfulData = allData.filter(item => item.success);

const profileData = successfulData.map(item => {
  const api = item.apiResponse;

  if (!api) {
    return {
      error: 'No API response',
      playerInfo: item.playerInfo
    };
  }

  const firstSeasonStats = api.firstSeasonStats;

  if (!firstSeasonStats) {
    return {
      error: 'No firstSeasonStats',
      playerInfo: item.playerInfo,
      player_id: api.id,
      player_name: api.name
    };
  }

  // 모든 섹션 추출
  const profileHeader = extractProfileHeader(api);
  const keyStats = extractKeyStats(firstSeasonStats);
  const attackStats = extractAttackStats(firstSeasonStats);
  const passingStats = extractPassingStats(firstSeasonStats);
  const possessionStats = extractPossessionStats(firstSeasonStats);
  const defenseStats = extractDefenseStats(firstSeasonStats);
  const disciplineStats = extractDisciplineStats(firstSeasonStats);
  const shotAnalysis = extractShotAnalysis(firstSeasonStats);

  // 모든 필드 병합
  return {
    // 메타 정보
    collection_date: item.timestamp,
    collection_week: new Date().toISOString().slice(0, 10),

    // Profile Header
    ...profileHeader,

    // Key Stats Cards
    ...keyStats,

    // Attack
    ...attackStats,

    // Passing
    ...passingStats,

    // Possession
    ...possessionStats,

    // Defense
    ...defenseStats,

    // Discipline
    ...disciplineStats,

    // Shot Analysis
    ...shotAnalysis
  };
});

// 에러 데이터 필터링 (선택사항)
const validProfiles = profileData.filter(p => !p.error);

// n8n 형식으로 반환
return validProfiles.map(data => ({ json: data }));

// 날짜 필터링 함수
function filterMatchesByWeek(matches, daysBack = 7) {
  const cutoffDate = new Date();
  cutoffDate.setDate(cutoffDate.getDate() - daysBack);

  return matches.filter(match => {
    if (!match.matchDate?.utcTime) return false;
    const matchDate = new Date(match.matchDate.utcTime);
    return matchDate > cutoffDate;
  });
}

// MVP 점수 계산
function calculateMvpScore(weeklyMatches) {
  if (!weeklyMatches.length) return 0;

  const totalGoals = weeklyMatches.reduce((sum, m) => sum + (m.goals || 0), 0);
  const totalAssists = weeklyMatches.reduce((sum, m) => sum + (m.assists || 0), 0);
  const totalMinutes = weeklyMatches.reduce((sum, m) => sum + (m.minutesPlayed || 0), 0);
  const motmCount = weeklyMatches.filter(m => m.playerOfTheMatch).length;

  const validRatings = weeklyMatches
    .filter(m => m.ratingProps?.rating && m.minutesPlayed > 0)
    .map(m => parseFloat(m.ratingProps.rating));

  const avgRating = validRatings.length 
    ? validRatings.reduce((sum, r) => sum + r, 0) / validRatings.length 
    : 0;

  return (
    (totalGoals + totalAssists) * 2.0 +
    avgRating +
    (totalMinutes / 90) +
    motmCount * 1.5
  );
}

// 메인 처리 로직
const allData = $input.all().map(item => item.json);
const successfulData = allData.filter(item => item.success);

const parsedData = successfulData.map(item => {
  const player = item.playerInfo;
  const api = item.apiResponse;

  // 시즌 통계 추출
  const mainLeagueStats = api.mainLeague?.stats || [];
  const statsMap = {};
  mainLeagueStats.forEach(stat => {
    statsMap[stat.localizedTitleId] = stat.value;
  });

  // 최근 50경기 (필터링용)
  const recentMatches = (api.recentMatches || []).slice(0, 50);

  // 최근 7일 경기 필터링
  const weeklyMatches = filterMatchesByWeek(recentMatches);

  // 주간 통계 계산
  const weeklyStats = weeklyMatches.length > 0 ? {
    matches: weeklyMatches.length,
    minutes: weeklyMatches.reduce((sum, m) => sum + (m.minutesPlayed || 0), 0),
    goals: weeklyMatches.reduce((sum, m) => sum + (m.goals || 0), 0),
    assists: weeklyMatches.reduce((sum, m) => sum + (m.assists || 0), 0),
    avg_rating: parseFloat(
      (weeklyMatches
        .filter(m => m.ratingProps?.rating && m.minutesPlayed > 0)
        .reduce((sum, m, _, arr) => sum + parseFloat(m.ratingProps.rating) / arr.length, 0)
      ).toFixed(2)
    ) || 0,
    mvp_score: parseFloat(calculateMvpScore(weeklyMatches).toFixed(2))
  } : null;

  // 시즌 통계
  const seasonStats = {
    matches: statsMap.matches_uppercase || 0,
    goals: statsMap.goals || 0,
    assists: statsMap.assists || 0,
    avg_rating: statsMap.rating || 0,
    yellow_cards: statsMap.yellow_cards || 0,
    red_cards: statsMap.red_cards || 0
  };

  // 최근 경기 기록 (최대 10경기)
  const recentMatchesFormatted = recentMatches.slice(0, 10).map(match => ({
    date: match.matchDate?.utcTime || null,
    opponent: match.opponentTeamName || 'Unknown',
    result: `${match.homeScore || 0}-${match.awayScore || 0}`,
    is_home: match.isHomeTeam || false,
    minutes: match.minutesPlayed || 0,
    goals: match.goals || 0,
    assists: match.assists || 0,
    rating: match.ratingProps?.rating || null,
    is_motm: match.playerOfTheMatch || false
  }));

  // 부상 상태
  const injuryStatus = api.injuryInformation ? {
    status: api.injuryInformation.name || 'Injured',
    expected_return: api.injuryInformation.expectedReturn?.expectedReturnFallback || 'Unknown'
  } : null;

  return {
    // 메타 정보
    collection_date: item.timestamp,
    week: new Date().toISOString().slice(0, 10),

    // 기본 정보
    id: player.id,
    name: player.name,
    name_kr: player.nameKr,
    team: api.primaryTeam?.teamName || 'Unknown',
    league: api.mainLeague?.leagueName || 'Unknown',
    position: api.positionDescription?.primaryPosition?.label || 'Unknown',

    // 주간 통계
    weekly_stats: weeklyStats,

    // 시즌 통계
    season_stats: seasonStats,

    // 최근 경기
    recent_matches: recentMatchesFormatted,

    // 부상 정보
    injury_status: injuryStatus,

    // 기타
    fotmob_url: `https://www.fotmob.com/players/${player.id}`,
    on_loan: api.primaryTeam?.onLoan || false,
    contract_end: api.contractEnd?.utcTime?.slice(0, 10) || null
  };
});

return parsedData.map(data => ({ json: data }));
